# -*- coding: utf-8 -*-
from pathlib import Path
import json,shutil
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'experiments/B_country';pub=ROOT/'work/github-pages-peers2002';d=json.load(open(R/'tables/analysis.json'));style=(ROOT/'scripts/policy_report.template.html').read_text().split('<style>')[1].split('</style>')[0]
rs=d['range_stats'];c={r['iso']:r for r in d['cells'] if r['version']=='B1'}
t='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>换个出生地 · 人生模拟实验室</title><style>__STYLE__</style></head><body><main><a href="index.html">← 人生模拟实验室</a><header><span class="eyebrow">B_COUNTRY / ENGINE 0.8.30</span><h1>同一个人，换个出生地</h1><p>9个国家、2种出生设置。把绝对人民币金额、当地收入尺度、寿命与幸存者构成分开看。</p><div class="grid"><div><div class="big">18,000</div><small>完整原始记录逐份核验</small></div><div><div class="big">1,000</div><small>同一批seed跨国家和版本复用</small></div><div><div class="big">2002</div><small>全部出生年份；未来人生属于模拟</small></div></div><nav><a href="#findings">主要发现</a><a href="#compare">年龄与金额</a><a href="#birth">出生状态</a><a href="#cases">极差案例</a><a href="#method">方法与下载</a></nav></header>
<section id="findings"><h2>01 / 出生地改变的不只是钱</h2>__FINDINGS__<p class="warn">“固定人格”固定的是预设性别、相对家境档位和天分抽样，不是九国出生情境完全一致。家境档位是本国内的相对位置，不是相同人民币家产。国别改变死亡、教育、工作和后续随机路径，不能解释成现实移民收益。</p></section>
<div class="controls"><label>出生设置 <select id="ver"><option value="B1">B1：固定预设人格与相对家境</option><option value="B2">B2：按各国重新抽取</option></select></label><label>观察年龄 <select id="age"><option>24</option><option>30</option><option>35</option><option>40</option><option>50</option><option>65</option><option value="death">终局（各自去世时）</option></select></label></div>
<section id="compare"><h2>02 / 绝对金额与当地尺度</h2><p>内部金额×3.5为人民币中国购买力等价值，不是汇率、现实预测或出生年份物价换算；月均收入=年收入÷12，不是税后工资。nwMed是净资产除以所在地中位年收入，不能称作当地财富中位数倍数。</p><div id="money" class="scroll"></div><p class="note">每国使用自身年龄快照，样本构成不同。终局是各自死亡时的值，不能当作同龄财富；净资产可为负。所在地可因迁移改变。</p><h3>同seed配对：所选国家 − 中国</h3><div id="pair" class="scroll"></div><p class="note">只用同版本、同seed双方均有快照者；不补零、不筛掉负值。净资产差中位数不是两个中位数相减，P10/P90是个体差分布，不是置信区间。B2的同seed不表示同一人格。</p><h3>样本流失</h3><div id="flow" class="scroll"></div><h3>九国共同有快照：固定共同样本</h3><div id="common" class="scroll"></div><p class="note">共同样本只用于观察样本构成敏感性，仍条件于九国都存活，可能大幅缩小，不能代表所有出生者。</p><h3>完整出生队列：寿命与终局</h3><div id="life" class="scroll"></div><p class="note">活到5岁按死亡年龄≥5计算。高等教育用终局edu≥4（大学或研究所）；有伴侣为死亡快照married，不是曾经结婚。摘要子女数包含引擎家庭角色，可能含亡故或继子女。“曾海外居住”是年度地点不同于出生国，包括收养、避难等，不等于成年工作移民。</p><h3>全部出生者寿命配对差</h3><div id="lifepair" class="scroll"></div></section>
<section id="birth"><h2>03 / “同一个人”究竟固定了什么</h2><p>B1脚本先按seed生成预设性别、1–5档家境与天分，九国复用；已核对1,000个seed的预设persona一致。国家出生逻辑仍可能改变实际出生状态。B2不覆盖这些抽样，性别、家境、天分均可能改变，不能把B2与B1之差解释成某一单独因素。</p><div id="audit" class="scroll"></div><p class="note">表中只列B1实际birthState相对预设persona发生变化的人数，每国分母1,000，各字段人数可重叠。变化原因需结合引擎和个案，不能一概归因收养。</p><p class="warn">没有B前缀seed专属的N_noise对照。既有N2使用P前缀，不按序号假配对，不扣除噪声，也不把残差称作纯运气。</p></section>
<section id="cases"><h2>04 / 九国寿命差最大的三个人</h2><p>按B1同seed九国寿命极差降序、seed打破平局，取前三名。这是刻意挑选的极端案例，不代表典型人生。各国记录均可展开，保留未成年死亡；极差也会随比较国家数量增加。</p><div id="caseList"></div></section>
<section id="method"><h2>05 / 校验与复算</h2><p>18,000个ID唯一且与任务计划完全一致；逐份读取gzip，核对seed、引擎版本和年龄快照，确认摘要和原始文件在分析期间未变化。全部出生者结果与年龄快照结果分开，未使用未来成功或寿命来筛选当期金额。</p><p>版本不是独立人群，跨国不是9,000个独立seed。不同国家即使预设人格一致，也不是相同家庭、制度或收入；结果只适用于这组国家与当前引擎。2002年出生者后续年龄包含未来模拟，不能当作已发生的现实统计。</p><p>完成采集：__FINISHED__；摘要SHA-256：<code style="overflow-wrap:anywhere">__HASH__</code></p>__DOWNLOADS__<p class="note">复算：将两份报告脚本及analyze_policy_reports.py恢复到项目scripts/，保留experiments/B_country数据，运行python3 scripts/analyze_country_report.py，再运行python3 scripts/build_country_report.py。构建器复用policy_report.template.html样式；下载文件部署时加了b_前缀，恢复时需去掉。</p></section></main><script>const D=__DATA__;
const $=id=>document.getElementById(id),fmt=x=>x==null?'—':Number(x).toLocaleString('zh-CN',{maximumFractionDigits:0}),pct=x=>x==null?'—':(x*100).toFixed(1)+'%',dec=x=>x==null?'—':x.toFixed(2),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function table(head,rows){return '<table><thead><tr>'+head.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function render(){let v=$('ver').value,a=$('age').value,isos=Object.keys(D.countries),get=(i,m)=>D.groups.find(r=>r.version===v&&r.iso===i&&r.age===a&&r.metric===m);$('money').innerHTML=table(['出生国','快照/出生数','月收入中位/元','净资产P10 / 中位 / P90元','净资产为负','净资产/当地中位年收入','年收入/当地中位年收入'],isos.map(i=>{let r=get(i,'nw');return [D.countries[i],r.n+'/1000',fmt(get(i,'income').median),[r.p10,r.median,r.p90].map(fmt).join(' / '),pct(r.negative),dec(get(i,'nwMed').median),dec(get(i,'incMed').median)]}));
$('pair').innerHTML=table(['国家减中国','配对数','净资产差P10 / 中位 / P90元','净资产差均值/元','月收入差中位/元','幸福差中位'],isos.filter(i=>i!=='CHN').map(i=>{let g=m=>D.pairs.find(r=>r.version===v&&r.iso===i&&r.age===a&&r.metric===m),r=g('nw');return [D.countries[i],r.n+(r.n<30?' ⚠ 小样本':''),[r.p10,r.median,r.p90].map(fmt).join(' / '),fmt(r.mean),fmt(g('income').median),dec(g('h').median)]}));
$('flow').innerHTML=table(['国家','计划','中国缺快照','该国缺快照','双方可比'],D.flows.filter(r=>r.version===v&&r.age===a).map(r=>[D.countries[r.iso],r.planned,r.china_missing,r.country_missing,r.both]));$('common').innerHTML=table(['国家','共同样本','净资产中位/元'],D.common.filter(r=>r.version===v&&r.age===a).map(r=>[D.countries[r.iso],r.n+(r.n<30?' ⚠ 小样本':''),fmt(r.median)]));
$('life').innerHTML=table(['国家','出生数','享年中位 / 均值','活到5岁','高等教育','曾海外居住','终局有伴侣','摘要子女均值'],D.cells.filter(r=>r.version===v).map(r=>[D.countries[r.iso],r.n,dec(r.life_median)+' / '+dec(r.life_mean),pct(r.survive5),pct(r.higher_edu),pct(r.ever_overseas),pct(r.death_partner),dec(r.kids_mean)]));$('lifepair').innerHTML=table(['国家减中国','配对数','寿命差P10 / 中位 / P90','均值'],D.life_pairs.filter(r=>r.version===v&&r.iso!=='CHN').map(r=>[D.countries[r.iso],r.n,[r.p10,r.median,r.p90].map(dec).join(' / '),dec(r.mean)]));}
$('audit').innerHTML=table(['国家','性别变化','家境变化','天分变化'],D.audit.filter(r=>r.version==='B1').map(r=>[D.countries[r.iso],r.sex_changed,r.q_changed,r.tal_changed]));
$('caseList').innerHTML=D.cases.map(c=>'<details><summary>'+esc(c.seed)+' · 九国寿命极差 '+c.range+' 岁</summary>'+c.lives.map(l=>'<details><summary>'+D.countries[l.iso]+' · '+esc(l.name)+' · 享年 '+l.age+'</summary><p>任务ID '+esc(l.id)+'；出生状态 '+esc(JSON.stringify(l.birth))+'</p><div class="log">'+l.log.map(z=>'<p><b>'+esc(z.a)+'岁</b> '+esc(z.text)+'</p>').join('')+'</div></details>').join('')+'</details>').join('');['ver','age'].forEach(id=>$(id).addEventListener('change',render));render();</script></body></html>'''
f=f'''<div class="grid"><div class="panel"><h3>同seed九国寿命极差</h3><p>B1的1,000个seed，极差中位 <b>{rs['median']:.0f}岁</b>，P10/P90为 {rs['p10']:.0f}/{rs['p90']:.0f} 岁。这是每个seed九国最长减最短，并非某国的平均优势。</p></div><div class="panel"><h3>完整出生队列的享年均值</h3><p>B1：中国 <b>{c['CHN']['life_mean']:.1f}</b>，尼日利亚 <b>{c['NGA']['life_mean']:.1f}</b>，日本 <b>{c['JPN']['life_mean']:.1f}</b> 岁。包含婴幼儿死亡，不只看幸存成年人。</p></div><div class="panel"><h3>绝对金额与相对位置</h3><p>同样的本地家境档位不等于同样购买力。下方同时给出人民币等价值、当地中位年收入倍数、同seed差值和共同幸存样本。</p></div></div>'''
files=sorted((R/'tables').glob('*.csv'));scripts=['analyze_country_report.py','build_country_report.py','analyze_policy_reports.py','policy_report.template.html']
for deploy in [False,True]:
 links=' · '.join(f'<a href="{"b_"+p.name if deploy else "tables/"+p.name}">{p.name}</a>' for p in files)+'<p>'+' · '.join(f'<a href="{"b_"+p if deploy else "../../scripts/"+p}">{p}</a>' for p in scripts)+'</p>'
 out=t
 for k,v in {'STYLE':style,'FINDINGS':f,'FINISHED':d['finished'],'HASH':d['source_hash'],'DOWNLOADS':links,'DATA':json.dumps(d,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')}.items():out=out.replace('__'+k+'__',v)
 (pub/'B_country.html' if deploy else R/'report.html').write_text(out)
for p in files:shutil.copyfile(p,pub/('b_'+p.name))
for p in scripts:shutil.copyfile(ROOT/'scripts'/p,pub/('b_'+p))
print('B built',len(out))
